import { Fragment } from 'react';
import { cx } from '../../utils/cx.js';
import ReviewLoopArtifact from './ReviewLoopArtifact.jsx';
import ReviewLoopRow from './ReviewLoopRow.jsx';
import {
  blockingSectionTitle,
  countsParts,
  countsText,
  findingStatus,
  findingLocation,
  findingRepeatNote,
  isBlockingFinding,
  isOffTaskFinding,
  recheckText,
  roundOutcomeLabel,
  roundTiming,
  testsReportText,
  testsTone,
} from './reviewLoopHelpers.js';

// One round of the loop: what the review found, what the chat decided about
// each finding it was sent (fixed + test, or rejected / out of scope + the
// evidence), and the round's saved texts. ``endReason`` is why the loop ended,
// on the round it ended in. It shows here only for a round with no review: that
// round has nothing else to show, and the pane's own notice covers the rest.
export default function ReviewLoopRound({ taskId, loopId, round, expanded, onToggle, now = 0, running = false, endReason = '' }) {
  const blocking = round.findings.filter(isBlockingFinding);
  const settled = round.findings.filter((finding) => finding.settled_by);
  const offTask = round.findings.filter((finding) => isOffTaskFinding(finding) && !finding.settled_by);
  const others = round.findings.filter((finding) => (
    !isBlockingFinding(finding) && !finding.settled_by && !isOffTaskFinding(finding)
  ));
  const blockingTitle = blockingSectionTitle(round, { running });
  const unreviewedReason = round.reviewed_at ? '' : endReason;
  const summary = round.reviewed_at
    ? <RoundCounts counts={round.counts} />
    : (unreviewedReason || 'not reviewed yet');
  // A clean-room sweep: a reviewer told nothing of the fixes, confirming the
  // clean round before it. A re-check: it read only what moved since the last
  // review, so its "clean" covers no more than that.
  const tagText = round.sweep ? 'Clean-room' : (round.rechecked_files ? recheckText(round.rechecked_files) : '');
  const tag = tagText ? <span className="review-loop-round-tag">{tagText}</span> : null;
  const runs = round.test_runs || [];
  return (
    <ReviewLoopRow
      className={cx('review-loop-round', `is-${round.outcome || 'active'}`)}
      data-round={round.number}
      name={`Round ${round.number}`}
      tag={tag}
      summary={summary}
      timing={roundTiming(round, now)}
      outcome={roundOutcomeLabel(round)}
      expanded={expanded}
      onToggle={() => onToggle(round.number)}
    >
      {unreviewedReason ? <p className="review-loop-round-reason">{unreviewedReason}</p> : null}
      <RoundTests runs={runs} />
      <FindingList title={blockingTitle} findings={blocking} round={round} running={running} />
      <FindingList title="Settled earlier — not sent again" findings={settled} round={round} running={running} />
      <FindingList title="Not part of this task — not sent" findings={offTask} round={round} running={running} />
      <FindingList title="Not blocking — reported only" findings={others} round={round} running={running} />
      <RoundArtifacts taskId={taskId} loopId={loopId} round={round} />
    </ReviewLoopRow>
  );
}

// "2 blocking · 7 minor · 2 nit", each count in its severity's colour — the
// same colours the open round gives its findings' badges.
function RoundCounts({ counts }) {
  const parts = countsParts(counts);
  if (!parts.length) { return countsText(counts); }
  return parts.map((part, index) => (
    <Fragment key={part.key}>
      {index ? ' · ' : null}
      <span className={cx('review-loop-count', part.severity && `is-${part.severity}`)}>{part.text}</span>
    </Fragment>
  ));
}

// What the main chat reported each time it ran the tests on this round's
// tree — several runs when failing tests were fixed in the round, oldest first.
function RoundTests({ runs }) {
  const numbered = runs.length > 1;
  // Runs are only ever appended, so a run's place is its identity.
  return runs.map((run, index) => (
    <RoundTestRun key={index} run={run} name={numbered ? `Run ${index + 1}: ` : ''} />
  ));
}

function RoundTestRun({ run, name }) {
  const failures = (run.failures || []).map((failure) => <li key={failure}>{failure}</li>);
  const failureList = failures.length ? <ul className="review-loop-tests-failures">{failures}</ul> : null;
  return (
    <section className={cx('review-loop-tests', `is-${testsTone(run)}`)}>
      <p className="review-loop-tests-summary">{`${name}${testsReportText(run)}`}</p>
      {failureList}
    </section>
  );
}

function FindingList({ title, findings, round, running }) {
  if (findings.length === 0) { return null; }
  const items = findings.map((finding, index) => (
    <FindingItem key={finding.id || `${finding.file}:${finding.line}:${index}`}
      finding={finding} round={round} running={running} />
  ));
  return (
    <section className="review-loop-findings">
      <h4>{title}</h4>
      <ul>{items}</ul>
    </section>
  );
}

function FindingItem({ finding, round, running }) {
  const id = finding.id ? <span className="review-loop-finding-id">{finding.id}</span> : null;
  const detail = finding.detail ? <p className="review-loop-finding-note">{finding.detail}</p> : null;
  const invariant = finding.invariant ? (
    <p className="review-loop-finding-note"><b>Invariant:</b> {finding.invariant}</p>
  ) : null;
  const newEvidence = finding.new_evidence ? (
    <p className="review-loop-finding-note"><b>Raised again with new evidence:</b> {finding.new_evidence}</p>
  ) : null;
  const settledBy = finding.settled_by ? (
    <p className="review-loop-finding-note">Settled by the decision on {finding.settled_by}.</p>
  ) : null;
  const repeatText = findingRepeatNote(finding);
  const repeat = repeatText ? <p className="review-loop-finding-note is-repeat">{repeatText}</p> : null;
  const decision = findingStatus(round, finding, { running });
  const decisionLine = decision ? (
    <p className={cx('review-loop-decision', `is-${decision.tone}`)}>
      <b>{decision.label}</b>
      <span>{decision.note}</span>
    </p>
  ) : null;
  return (
    <li className="review-loop-finding">
      {id}
      <span className={cx('review-loop-severity', `is-${finding.severity.toLowerCase()}`)}>
        {finding.severity}
      </span>
      <span className="review-loop-finding-title">{finding.title}</span>
      <span className="review-loop-finding-location">{findingLocation(finding)}</span>
      {detail}
      {invariant}
      {newEvidence}
      {settledBy}
      {repeat}
      {decisionLine}
    </li>
  );
}

function RoundArtifacts({ taskId, loopId, round }) {
  const diffName = round.rechecked_files ? 'The whole change' : 'Diff the reviewer saw';
  const diffLabel = `${diffName} (${round.diff_files} file(s) in ${round.diff_repos} repo(s))`;
  // Failing tests sent back carry no per-finding answers, so no reply file.
  const answeredFindings = round.fixed_at && !round.tests_fixes;
  const runs = (round.test_runs || []).length;
  const shown = [
    { kind: 'review', label: 'Reviewer’s full report', when: round.reviewed_at },
    { kind: 'prompt', label: 'Message sent to the chat', when: round.sent_at },
    { kind: 'response', label: 'The chat’s reply to the findings', when: answeredFindings },
    { kind: 'tests', label: runs > 1 ? 'The chat’s latest test report' : 'The chat’s test report', when: runs },
    { kind: 'changes', label: `What the reviewer re-checked (${round.rechecked_files} file(s))`, when: round.rechecked_files },
    { kind: 'diff', label: diffLabel, when: round.diff_files },
  ].filter((artifact) => artifact.when);
  const artifacts = shown.map(({ kind, label }) => (
    <ReviewLoopArtifact key={kind} taskId={taskId} loopId={loopId} round={round.number} kind={kind} label={label} />
  ));
  return <div className="review-loop-artifacts">{artifacts}</div>;
}
